1967. pub struct ControllerModel {
1968.     pub reconcile_model: ReconcileModel,
1969.     pub external_model: Option<ExternalModel>,
1970. }
1971. 
1972. impl Cluster {
1973. 
1974.     pub open spec fn init(self) -> StatePred<ClusterState> {
1975.         |s: ClusterState| {
1976.             // The API server is initialized...
1977.             &&& (api_server(self.installed_types).init)(s.api_server)
1978.             // and the built-in controllers are initialized...
1979.             &&& (builtin_controllers().init)(())
1980.             // and the network is initialized...
1981.             &&& (network().init)(s.network)
1982.             // and message drop is enabled...
1983.             &&& s.req_drop_enabled
1984.             // and pod monkey is enabled...
1985.             &&& s.pod_monkey_enabled
1986.             // and for each controller...
1987.             &&& forall |key| #[trigger] self.controller_models.contains_key(key)
1988.                 ==> {
1989.                     let model = self.controller_models[key];
1990.                     // its internal state exists...
1991.                     &&& s.controller_and_externals.contains_key(key)
1992.                     // and is initialized...
1993.                     &&& (controller(model.reconcile_model, key).init)(s.controller_and_externals[key].controller)
1994.                     // and crash for this controller is enabled...
1995.                     &&& s.controller_and_externals[key].crash_enabled
1996.                     // and if the controller has an associated external system...
1997.                     &&& model.external_model is Some
1998.                         ==> {
1999.                             // the internal state of that external system exists...
2000.                             &&& s.controller_and_externals[key].external is Some
2001.                             // and is initialized.
2002.                             &&& (external(model.external_model->0).init)(s.controller_and_externals[key].external->0)
2003.                         }
2004.                 }
2005.         }
2006.     }
2007. 
2008.     pub open spec fn next(self) -> ActionPred<ClusterState> {
2009.         |s, s_prime: ClusterState| exists |step: Step| self.next_step(s, s_prime, step)
2010.     }
2011. 
2012.     pub open spec fn next_step(self, s: ClusterState, s_prime: ClusterState, step: Step) -> bool {
