2826. pub open spec fn reconcile_core(v_replica_set: VReplicaSetView, resp_o: Option<ResponseView<VoidERespView>>, state: VReplicaSetReconcileState) -> (VReplicaSetReconcileState, Option<RequestView<VoidEReqView>>) {
2827.     let namespace = v_replica_set.metadata.namespace.unwrap();
2828.     match &state.reconcile_step {
2829.         VReplicaSetRecStepView::Init => {
2830.             if v_replica_set.metadata.deletion_timestamp.is_some() {
2831.                 let state_prime = VReplicaSetReconcileState {
2832.                     reconcile_step: VReplicaSetRecStepView::Done,
2833.                     ..state
2834.                 };
2835.                 (state_prime, None)
2836.             } else {
2837.                 let req = APIRequest::ListRequest(ListRequest {
2838.                     kind: PodView::kind(),
2839.                     namespace: namespace,
2840.                 });
2841.                 let state_prime = VReplicaSetReconcileState {
2842.                     reconcile_step: VReplicaSetRecStepView::AfterListPods,
2843.                     ..state
2844.                 };
2845.                 (state_prime, Some(RequestView::KRequest(req)))
2846.             }
2847.         },
2848.         VReplicaSetRecStepView::AfterListPods => {
2849.             let pred1 = (resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_ListResponse());
2850.             let pred2 = resp_o.unwrap().get_KResponse_0().get_ListResponse_0().res;
2851.             if !(pred1 && pred2 is Ok) {
2852.                 (error_state(state), None)
2853.             } else {
2854.                 let objs = pred2.unwrap();
2855.                 let pods_or_none = objects_to_pods(objs);
2856.                 if pods_or_none.is_none() {
2857.                     (error_state(state), None)
2858.                 } else {
2859.                     let pods = pods_or_none.unwrap();
2860.                     let filtered_pods = filter_pods(pods, v_replica_set);
2861.                     let replicas = v_replica_set.spec.replicas.unwrap_or(0);
2862.                     if replicas < 0 {
2863.                         (error_state(state), None)
2864.                     } else {
2865.                         let desired_replicas = replicas;
2866.                         if filtered_pods.len() == desired_replicas {
2867.                             let state_prime = VReplicaSetReconcileState {
2868.                                 reconcile_step: VReplicaSetRecStepView::Done,
2869.                                 ..state
2870.                             };
2871.                             (state_prime, None)
2872.                         } else if filtered_pods.len() < desired_replicas {
2873.                             let diff =  desired_replicas - filtered_pods.len();
2874.                             let pod = make_pod(v_replica_set);
2875.                             let req = APIRequest::CreateRequest(CreateRequest {
2876.                                 namespace: namespace,
2877.                                 obj: pod.marshal(),
2878.                             });
2879.                             let state_prime = VReplicaSetReconcileState {
2880.                                 reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2881.                                 ..state
2882.                             };
2883.                             (state_prime, Some(RequestView::KRequest(req)))
2884.                         } else {
2885.                             let diff = filtered_pods.len() - desired_replicas;
2886.                             let pod_name_or_none = filtered_pods[diff - 1].metadata.name;
2887.                             if pod_name_or_none.is_none() {
2888.                                 (error_state(state), None)
2889.                             } else {
2890.                                 let req = APIRequest::GetThenDeleteRequest(GetThenDeleteRequest {
2891.                                     key: ObjectRef {
2892.                                         kind: PodView::kind(),
2893.                                         name: pod_name_or_none.unwrap(),
2894.                                         namespace: namespace,
2895.                                     },
2896.                                     owner_ref: v_replica_set.controller_owner_ref(),
2897.                                 });
2898.                                 let state_prime = VReplicaSetReconcileState {
2899.                                     reconcile_step: VReplicaSetRecStepView::AfterDeletePod((diff - 1) as nat),
2900.                                     filtered_pods: Some(filtered_pods),
2901.                                     ..state
2902.                                 };
2903.                                 (state_prime, Some(RequestView::KRequest(req)))
2904.                             }
2905.                         }
2906.                     }
2907.                 }
2908.             }
2909.         },
2910.         VReplicaSetRecStepView::AfterCreatePod(diff) => {
2911.             let diff = *diff;
2912.             let predicate1 = ( resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_CreateResponse() );
2913.             let predicate2 = resp_o.unwrap().get_KResponse_0().get_CreateResponse_0().res;
2914.             if !(predicate1 && predicate2 is Ok) {
2915.                 (error_state(state), None)
2916.             } else if diff == 0 {
2917.                 let state_prime = VReplicaSetReconcileState {
2918.                     reconcile_step: VReplicaSetRecStepView::Done,
2919.                     ..state
2920.                 };
2921.                 (state_prime, None)
2922.             } else {
2923.                 let pod = make_pod(v_replica_set);
2924.                 let req = APIRequest::CreateRequest(CreateRequest {
2925.                     namespace: namespace,
2926.                     obj: pod.marshal(),
2927.                 });
2928.                 let state_prime = VReplicaSetReconcileState {
2929.                     reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2930.                     ..state
2931.                 };
2932.                 (state_prime, Some(RequestView::KRequest(req)))
2933.             }
2934.         },
2935.         VReplicaSetRecStepView::AfterDeletePod(diff) => {
2936.             let diff = *diff;
2937.             let predicate1 = (resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_GetThenDeleteResponse());
2938.             let predicate2 = resp_o.unwrap().get_KResponse_0().get_GetThenDeleteResponse_0().res;
2939.                 
2940.             if !(predicate1 && predicate2 is Ok) {
2941.                 (error_state(state), None)
2942.             } else if diff == 0 {
2943.                 let state_prime = VReplicaSetReconcileState {
2944.                     reconcile_step: VReplicaSetRecStepView::Done,
2945.                     ..state
2946.                 };
2947.                 (state_prime, None)
2948.             } else {
2949.                 if state.filtered_pods.is_none() {
2950.                     (error_state(state), None)
2951.                 } else if diff > state.filtered_pods.unwrap().len() {
2952.                     (error_state(state), None)
2953.                 } else {
2954.                     let pod_name_or_none = state.filtered_pods.unwrap()[diff - 1].metadata.name;
2955.                     if pod_name_or_none.is_none() {
2956.                         (error_state(state), None)
2957.                     } else {
2958.                         let req = APIRequest::GetThenDeleteRequest(GetThenDeleteRequest {
2959.                             key: ObjectRef {
2960.                                 kind: PodView::kind(),
2961.                                 name: pod_name_or_none.unwrap(),
2962.                                 namespace: namespace,
2963.                             },
2964.                             owner_ref: v_replica_set.controller_owner_ref(),
2965.                         });
2966.                         let state_prime = VReplicaSetReconcileState {
2967.                             reconcile_step: VReplicaSetRecStepView::AfterDeletePod((diff - 1) as nat),
2968.                             ..state
2969.                         };
2970.                         (state_prime, Some(RequestView::KRequest(req)))
2971.                     }
2972.                 }
2973.             }
2974.         },
2975.         _ => {
2976.             (state, None)
2977.         }
2978.     }
2979. }
