3567.             // period set in the deletion option is another reason. Currently we do not model the graceful period
3568.             // option so we don't model how the API server checks whether a deletion should be graceful.
3569.             // However, even without a graceful period option, deleting a Pod can still be graceful depending on its
3570.             // spec content (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/apis/core/types.go#L3256)
3571.             // because Pod implements CheckGracefulDelete (see https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/registry/core/pod/strategy.go#L168).
3572.             // This is irrelevant to application controllers that do not manage pods, and acceptable for verifying
3573.             // low-level built-in controllers because they are supposed to treat terminating pods as non-existing pods.
3574.             if obj.metadata.deletion_timestamp is Some {
3575.                 // A deletion timestamp is already set so no need to bother it.
3576.                 (s, DeleteResponse{res: Ok(())})
3577.             } else {
3578.                 let stamped_obj_with_new_rv = obj.with_deletion_timestamp(deletion_timestamp())
3579.                                                  .with_resource_version(s.resource_version_counter);
3580.                 (APIServerState {
3581.                     // Here we use req.key, instead of stamped_obj.object_ref(), to insert to the map.
3582.                     // This is intended because using stamped_obj.object_ref() will require us to use
3583.                     // the invariant each_object_in_etcd_is_well_formed a lot more frequently:
3584.                     // we need this invariant to convince Verus that the stamped_obj is well formed
3585.                     // so the key we use to insert to the map is the same as req.key.
3586.                     resources: s.resources.insert(req.key, stamped_obj_with_new_rv),
3587.                     resource_version_counter: s.resource_version_counter + 1,
3588.                     ..s
3589.                 }, DeleteResponse{res: Ok(())})
3590.             }
3591.         } else {
3592.             // The object can be immediately removed from the key-value store.
3593.             //
3594.             // NOTE: In some very corner case, the API server *seems* to first updates the object (to update its finalizers)
3595.             // and then deletes the object immediately, which makes the entire Delete operation not atomic.
3596.             // However, this only happens in the orphan or foreground deletion mode, so we do not model this
3597.             // seemingly non-atomic behavior for now.
3598.             // For more details, see how the API server updates the object in the middle of handling deletion requests:
3599.             // https://github.com/kubernetes/kubernetes/blob/v1.30.0/staging/src/k8s.io/apiserver/pkg/registry/generic/registry/store.go#L1009
3600.             (APIServerState {
3601.                 resources: s.resources.remove(req.key),
3602.                 resource_version_counter: s.resource_version_counter + 1,
3603.                 ..s
3604.             }, DeleteResponse{res: Ok(())})
3605.         }
3606.     }
3607. }
