3616. pub open spec fn update_request_admission_check_helper(installed_types: InstalledTypes, name: StringView, namespace: StringView, obj: DynamicObjectView, s: APIServerState) -> Option<APIError> {
3617.     let key = ObjectRef {
3618.         kind: obj.kind,
3619.         namespace: namespace,
3620.         name: name,
3621.     };
3622.     if obj.metadata.name is None {
3623.         // Update fails because the name of the object is not provided
3624.         Some(APIError::BadRequest)
3625.     } else if name != obj.metadata.name->0 {
3626.         // Update fails because the name of the provided object
3627.         // does not match the name sent on the request
3628.         Some(APIError::BadRequest)
3629.     } else if obj.metadata.namespace is Some
3630.         && namespace != obj.metadata.namespace->0 {
3631.         // Update fails because the namespace of the provided object
3632.         // does not match the namespace sent on the request
3633.         Some(APIError::BadRequest)
3634.     } else if !unmarshallable_object(obj, installed_types) {
3635.         // Update fails because the provided object is not well formed
3636.         // TODO: should the error be BadRequest?
3637.         Some(APIError::BadRequest)
3638.     } else if !s.resources.contains_key(key) {
3639.         // Update fails because the object does not exist
3640.         // TODO: check AllowCreateOnUpdate() to see whether to support create-on-update
3641.         Some(APIError::ObjectNotFound)
3642.     } else if obj.metadata.resource_version is None
3643.         && !allow_unconditional_update(key.kind) {
3644.         // Update fails because the object does not provide a rv and unconditional update is not supported
3645.         Some(APIError::Invalid)
3646.     } else if obj.metadata.resource_version is Some
3647.         && obj.metadata.resource_version != s.resources[key].metadata.resource_version {
3648.         // Update fails because the object has a wrong rv
3649.         Some(APIError::Conflict)
3650.     } else if obj.metadata.uid is Some
3651.         && obj.metadata.uid != s.resources[key].metadata.uid {
3652.         // Update fails because the object has a wrong uid
3653.         Some(APIError::Conflict)
3654.     } else {
3655.         None
3656.     }
3657. }
