3663. pub open spec fn updated_object(req: UpdateRequest, old_obj: DynamicObjectView) -> DynamicObjectView {
3664.     let updated_obj = DynamicObjectView {
3665.         kind: req.obj.kind,
3666.         metadata: ObjectMetaView {
3667.             namespace: Some(req.namespace), // Overwrite namespace since it might not be provided
3668.             resource_version: old_obj.metadata.resource_version, // Overwrite rv since it might not be provided
3669.             uid: old_obj.metadata.uid, // Overwrite uid since it might not be provided
3670.             deletion_timestamp: old_obj.metadata.deletion_timestamp, // Ignore any change to deletion_timestamp
3671.             ..req.obj.metadata
3672.         },
3673.         spec: req.obj.spec,
3674.         status: old_obj.status, // Ignore any change to status
3675.     };
3676.     updated_obj
3677. }
