3679. pub open spec fn updated_object_validity_check(updated_obj: DynamicObjectView, old_obj: DynamicObjectView, installed_types: InstalledTypes) -> Option<APIError> {
3680.     if metadata_validity_check(updated_obj) is Some {
3681.         metadata_validity_check(updated_obj)
3682.     } else if metadata_transition_validity_check(updated_obj, old_obj) is Some {
3683.         metadata_transition_validity_check(updated_obj, old_obj)
3684.     } else if object_validity_check(updated_obj, installed_types) is Some {
3685.         object_validity_check(updated_obj, installed_types)
3686.     } else if object_transition_validity_check(updated_obj, old_obj, installed_types) is Some {
3687.         object_transition_validity_check(updated_obj, old_obj, installed_types)
3688.     } else {
3689.         None
3690.     }
3691. }
