3859. pub open spec fn handle_get_then_delete_request_msg(msg: Message, s: APIServerState) -> (APIServerState, Message)
3860.     recommends
3861.         msg.content.is_get_then_delete_request(),
3862. {
3863.     let req = msg.content.get_get_then_delete_request();
3864.     // Step 1: get the object
3865.     let get_req = GetRequest {
3866.         key: req.key
3867.     };
3868.     let get_resp = handle_get_request(get_req, s);
3869.     match get_resp.res {
3870.         Ok(_) => {
3871.             let current_obj = s.resources[req.key()];
3872.             // Step 2: if the object exists, perform a check using a predicate on object
3873.             // The predicate: Is the current object owned by req.owner_ref?
3874.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3875.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3876.                 // Step 3: if the check passes, delete the object
3877.                 let delete_req = DeleteRequest {
3878.                     key: req.key,
3879.                     preconditions: None,
3880.                 };
3881.                 let (s_prime, delete_resp) = handle_delete_request(delete_req, s);
3882.                 (s_prime, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: delete_resp.res}))
3883.             } else {
3884.                 (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(APIError::TransactionAbort)}))
3885.             }
3886.         }
3887.         Err(err) => (s, form_get_then_delete_resp_msg(msg, GetThenDeleteResponse {res: Err(err)}))
3888.     }
3889. }
