3891. pub open spec fn handle_get_then_update_request_msg(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3892.     recommends
3893.         msg.content.is_get_then_update_request(),
3894. {
3895.     let req = msg.content.get_get_then_update_request();
3896.     // Step 1: get the object
3897.     let get_req = GetRequest {
3898.         key: req.key()
3899.     };
3900.     let get_resp = handle_get_request(get_req, s);
3901.     match get_resp.res {
3902.         Ok(_) => {
3903.             let current_obj = s.resources[req.key()];
3904.             // Step 2: if the object exists, perform a check using a predicate on object
3905.             // The predicate: Is the current object owned by req.owner_ref?
3906.             // TODO: the predicate should be provided by clients instead of the hardcoded one
3907.             if current_obj.metadata.owner_references_contains(req.owner_ref) {
3908.                 // Step 3: if the check passes, overwrite the object with the new one
3909.                 // Note that resource_version and uid comes from the current object to avoid conflict error
3910.                 let new_obj = DynamicObjectView {
3911.                     metadata: ObjectMetaView {
3912.                         resource_version: current_obj.metadata.resource_version,
3913.                         uid: current_obj.metadata.uid,
3914.                         ..req.obj.metadata
3915.                     },
3916.                     ..req.obj
3917.                 };
3918.                 let update_req = UpdateRequest {
3919.                     name: req.name,
3920.                     namespace: req.namespace,
3921.                     obj: new_obj,
3922.                 };
3923.                 let (s_prime, update_resp) = handle_update_request(installed_types, update_req, s);
3924.                 (s_prime, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: update_resp.res}))
3925.             } else {
3926.                 (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(APIError::TransactionAbort)}))
3927.             }
3928.         }
3929.         Err(err) => (s, form_get_then_update_resp_msg(msg, GetThenUpdateResponse {res: Err(err)}))
3930.     }
3931. }
