3933. pub open spec fn transition_by_etcd(installed_types: InstalledTypes, msg: Message, s: APIServerState) -> (APIServerState, Message)
3934.     recommends
3935.         msg.content.is_APIRequest(),
3936. {
3937.     match msg.content.get_APIRequest_0() {
3938.         APIRequest::GetRequest(_) => handle_get_request_msg(msg, s),
3939.         APIRequest::ListRequest(_) => handle_list_request_msg(msg, s),
3940.         APIRequest::CreateRequest(_) => handle_create_request_msg(installed_types, msg, s),
3941.         APIRequest::DeleteRequest(_) => handle_delete_request_msg(msg, s),
3942.         APIRequest::UpdateRequest(_) => handle_update_request_msg(installed_types, msg, s),
3943.         APIRequest::UpdateStatusRequest(_) => handle_update_status_request_msg(installed_types, msg, s),
3944.         APIRequest::GetThenDeleteRequest(_) => handle_get_then_delete_request_msg(msg, s),
3945.         APIRequest::GetThenUpdateRequest(_) => handle_get_then_update_request_msg(installed_types, msg, s),
3946.     }
3947. }
