3949. pub open spec fn handle_request(installed_types: InstalledTypes) -> APIServerAction {
3950.     Action {
3951.         precondition: |input: APIServerActionInput, s: APIServerState| {
3952.             &&& input.recv is Some
3953.             &&& input.recv->0.content.is_APIRequest()
3954.         },
3955.         transition: |input: APIServerActionInput, s: APIServerState| {
3956.             let (s_prime, etcd_resp) = transition_by_etcd(installed_types, input.recv->0, s);
3957.             (s_prime, APIServerActionOutput {
3958.                 send: Multiset::singleton(etcd_resp)
3959.             })
3960.         },
3961.     }
3962. }
