3964. pub open spec fn api_server(installed_types: InstalledTypes) -> APIServerStateMachine {
3965.     StateMachine {
3966.         init: |s: APIServerState| {
3967.             s.resources == Map::<ObjectRef, DynamicObjectView>::empty()
3968.         },
3969.         actions: set![handle_request(installed_types)],
3970.         step_to_action: |step: APIServerStep| {
3971.             match step {
3972.                 APIServerStep::HandleRequest => handle_request(installed_types),
3973.             }
3974.         },
3975.         action_input: |step: APIServerStep, input: APIServerActionInput| {
3976.             input
3977.         }
3978.     }
3979. }
