3983. pub open spec fn run_garbage_collector() -> BuiltinControllersAction {
3984.     Action {
3985.         precondition: |input: BuiltinControllersActionInput, s: ()| {
3986.             let resources = input.resources;
3987.             let key = input.key;
3988.             let owner_references = resources[key].metadata.owner_references->0;
3989.             // The garbage collector is chosen by the top level state machine
3990.             &&& input.choice.is_GarbageCollector()
3991.             // The object exists in the cluster state
3992.             &&& resources.contains_key(input.key)
3993.             // and it has at least one owner reference
3994.             &&& resources[key].metadata.owner_references is Some
3995.             &&& resources[key].metadata.owner_references->0.len() > 0
3996.             // The garbage collector decides whether to delete an object by checking its owner references,
3997.             // it deletes the object if for each owner reference...
3998.             &&& forall |i| #![trigger owner_references[i]] 0 <= i < owner_references.len() ==> {
3999.                 // the referred owner object does not exist in the cluster state
4000.                 ||| !resources.contains_key(owner_reference_to_object_reference(owner_references[i], key.namespace))
4001.                 // or it exists but has a different uid
4002.                 // (which means the actual owner was deleted and another object with the same name gets created again)
4003.                 ||| resources[owner_reference_to_object_reference(owner_references[i], key.namespace)].metadata.uid != Some(owner_references[i].uid)
4004.             }
4005.         },
4006.         transition: |input: BuiltinControllersActionInput, s: ()| {
4007.             // GC set the preconditions to the object's uid in its delete request
4008.             // See https://github.com/kubernetes/kubernetes/blob/v1.30.0/pkg/controller/garbagecollector/operations.go#L52-L61
4009.             let preconditions = PreconditionsView {
4010.                 uid: input.resources[input.key].metadata.uid,
4011.                 resource_version: None,
4012.             };
4013.             let delete_req_msg = built_in_controller_req_msg(
4014.                 input.rpc_id_allocator.allocate().1, delete_req_msg_content(input.key, Some(preconditions))
4015.             );
4016.             let output = BuiltinControllersActionOutput {
4017.                 send: Multiset::singleton(delete_req_msg),
4018.                 rpc_id_allocator: input.rpc_id_allocator.allocate().0,
4019.             };
4020.             ((), output)
4021.         },
4022.     }
4023. }
