4048. pub open spec fn run_scheduled_reconcile(model: ReconcileModel) -> ControllerAction {
4049.     Action {
4050.         precondition: |input: ControllerActionInput, s: ControllerState| {
4051.             &&& input.scheduled_cr_key is Some
4052.             &&& input.scheduled_cr_key->0.kind == model.kind
4053.             &&& s.scheduled_reconciles.contains_key(input.scheduled_cr_key->0)
4054.             &&& input.recv is None
4055.             &&& !s.ongoing_reconciles.contains_key(input.scheduled_cr_key->0)
4056.         },
4057.         transition: |input: ControllerActionInput, s: ControllerState| {
4058.             let cr_key = input.scheduled_cr_key->0;
4059.             let (new_allocator, reconcile_id) = s.reconcile_id_allocator.allocate();
4060.             let initialized_ongoing_reconcile = OngoingReconcile {
4061.                 triggering_cr: s.scheduled_reconciles[cr_key],
4062.                 pending_req_msg: None,
4063.                 local_state: (model.init)(),
4064.                 reconcile_id: reconcile_id
4065.             };
4066.             let s_prime = ControllerState {
4067.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
4068.                 scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
4069.                 reconcile_id_allocator: new_allocator,
4070.                 ..s
4071.             };
4072.             let output = ControllerActionOutput {
4073.                 send: Multiset::empty(),
4074.                 rpc_id_allocator: input.rpc_id_allocator,
4075.             };
4076.             (s_prime, output)
4077.         },
4078.     }
4079. }
