4467.                 &&& state.filtered_pods is Some ==>
4468.                 // Maintained across deletes, 
4469.                 // maintained across creates since all new keys with generate_name
4470.                 // are unique, maintained across updates since there are
4471.                 // no updates.
4472.                     forall |i| #![trigger filtered_pods[i]] 0 <= i < filtered_pods.len() ==>
4473.                     (
