2826. pub open spec fn reconcile_core(v_replica_set: VReplicaSetView, resp_o: Option<ResponseView<VoidERespView>>, state: VReplicaSetReconcileState) -> (VReplicaSetReconcileState, Option<RequestView<VoidEReqView>>) {
2827.     let namespace = v_replica_set.metadata.namespace.unwrap();
2828.     match &state.reconcile_step {
2829.         VReplicaSetRecStepView::Init => {
2830.             if v_replica_set.metadata.deletion_timestamp.is_some() {
2831.                 let state_prime = VReplicaSetReconcileState {
2832.                     reconcile_step: VReplicaSetRecStepView::Done,
2833.                     ..state
2834.                 };
2835.                 (state_prime, None)
2836.             } else {
2837.                 let req = APIRequest::ListRequest(ListRequest {
2838.                     kind: PodView::kind(),
2839.                     namespace: namespace,
2840.                 });
2841.                 let state_prime = VReplicaSetReconcileState {
2842.                     reconcile_step: VReplicaSetRecStepView::AfterListPods,
2843.                     ..state
2844.                 };
2845.                 (state_prime, Some(RequestView::KRequest(req)))
2846.             }
2847.         },
2848.         VReplicaSetRecStepView::AfterListPods => {
2849.             let pred1 = (resp_o is Some && resp_o.unwrap().is_KResponse() && resp_o.unwrap().get_KResponse_0().is_ListResponse());
2850.             let pred2 = resp_o.unwrap().get_KResponse_0().get_ListResponse_0().res;
2851.             if !(pred1 && pred2 is Ok) {
2852.                 (error_state(state), None)
2853.             } else {
2854.                 let objs = pred2.unwrap();
2855.                 let pods_or_none = objects_to_pods(objs);
2856.                 if pods_or_none.is_none() {
2857.                     (error_state(state), None)
2858.                 } else {
2859.                     let pods = pods_or_none.unwrap();
2860.                     let filtered_pods = filter_pods(pods, v_replica_set);
2861.                     let replicas = v_replica_set.spec.replicas.unwrap_or(0);
2862.                     if replicas < 0 {
2863.                         (error_state(state), None)
2864.                     } else {
2865.                         let desired_replicas = replicas;
2866.                         if filtered_pods.len() == desired_replicas {
2867.                             let state_prime = VReplicaSetReconcileState {
2868.                                 reconcile_step: VReplicaSetRecStepView::Done,
2869.                                 ..state
2870.                             };
2871.                             (state_prime, None)
2872.                         } else if filtered_pods.len() < desired_replicas {
2873.                             let diff =  desired_replicas - filtered_pods.len();
2874.                             let pod = make_pod(v_replica_set);
2875.                             let req = APIRequest::CreateRequest(CreateRequest {
2876.                                 namespace: namespace,
2877.                                 obj: pod.marshal(),
2878.                             });
2879.                             let state_prime = VReplicaSetReconcileState {
2880.                                 reconcile_step: VReplicaSetRecStepView::AfterCreatePod((diff - 1) as nat),
2881.                                 ..state
2882.                             };
2883.                             (state_prime, Some(RequestView::KRequest(req)))
2884.                         } else {
2885.                             let diff = filtered_pods.len() - desired_replicas;
