3479. #[verifier(inline)]
3480. pub open spec fn handle_create_request(installed_types: InstalledTypes, req: CreateRequest, s: APIServerState) -> (APIServerState, CreateResponse) {
3481.     if create_request_admission_check(installed_types, req, s) is Some {
3482.         // Creation fails.
3483.         (s, CreateResponse{res: Err(create_request_admission_check(installed_types, req, s)->0)})
3484.     } else {
3485.         let created_obj = DynamicObjectView {
3486.             kind: req.obj.kind,
3487.             metadata: ObjectMetaView {
3488.                 // Set name for new object if name is not provided, here we generate
3489.                 // a unique name. The uniqueness is guaranteed by generated_name_is_unique.
3490.                 name: if req.obj.metadata.name is Some {
3491.                     req.obj.metadata.name
3492.                 } else {
3493.                     Some(generate_name(s))
3494.                 },
3495.                 namespace: Some(req.namespace), // Set namespace for new object
3496.                 resource_version: Some(s.resource_version_counter), // Set rv for new object
3497.                 uid: Some(s.uid_counter), // Set uid for new object
3498.                 deletion_timestamp: None, // Unset deletion timestamp for new object
3499.                 ..req.obj.metadata
3500.             },
3501.             spec: req.obj.spec,
3502.             status: marshalled_default_status(req.obj.kind, installed_types), // Overwrite the status with the default one
3503.         };
3504.         if s.resources.contains_key(created_obj.object_ref()) {
3505.             // Note 1: You might find this branch redundant since we already have
3506.             // generated_name_is_unique which guarantees that the created_obj's
3507.             // key is different from any existing keys even if name was not provided.
3508.             // But we still add this branch just to avoid calling generated_name_is_unique
3509.             // when we want to show that create without a provided name does not override
3510.             // an existing object when writing proofs.
3511.             //
3512.             // Note 2: Adding this branch also means that if we want to prove the object
3513.             // is eventually created by a create request without the name provided,
3514.             // we need to explicitly call generated_name_is_unique to show that
3515.             // we do not fall into this branch.
3516.             (s, CreateResponse{res: Err(APIError::ObjectAlreadyExists)})
3517.         } else if created_object_validity_check(created_obj, installed_types) is Some {
3518.             // Creation fails.
3519.             (s, CreateResponse{res: Err(created_object_validity_check(created_obj, installed_types)->0)})
3520.         } else {
3521.             // Creation succeeds.
3522.             (APIServerState {
3523.                 resources: s.resources.insert(created_obj.object_ref(), created_obj),
3524.                 uid_counter: s.uid_counter + 1,
3525.                 resource_version_counter: s.resource_version_counter + 1,
3526.                 ..s
3527.             }, CreateResponse{res: Ok(created_obj)})
3528.         }
3529.     }
3530. }
