3532. pub open spec fn delete_request_admission_check(req: DeleteRequest, s: APIServerState) -> Option<APIError> {
3533.     if !s.resources.contains_key(req.key) {
3534.         // Deletion fails because the object does not exist
3535.         Some(APIError::ObjectNotFound)
3536.     } else if req.preconditions is Some {
3537.         let preconditions = req.preconditions->0;
3538.         if preconditions.uid is Some && preconditions.uid != s.resources[req.key].metadata.uid {
3539.             // Deletion fails because the uid of the object does not match the uid in the precondition
3540.             Some(APIError::Conflict)
3541.         } else if preconditions.resource_version is Some && preconditions.resource_version != s.resources[req.key].metadata.resource_version {
3542.             // Deletion fails because the resource version of the object does not match the resource version in the precondition
3543.             Some(APIError::Conflict)
3544.         } else {
3545.             None
3546.         }
3547.     } else {
3548.         None
3549.     }
3550. }
