3668.             resource_version: old_obj.metadata.resource_version, // Overwrite rv since it might not be provided
3669.             uid: old_obj.metadata.uid, // Overwrite uid since it might not be provided
3670.             deletion_timestamp: old_obj.metadata.deletion_timestamp, // Ignore any change to deletion_timestamp
3671.             ..req.obj.metadata
