3897.     let get_req = GetRequest {
3898.         key: req.key()
3899.     };
3900.     let get_resp = handle_get_request(get_req, s);
3901.     match get_resp.res {
3902.         Ok(_) => {
3903.             let current_obj = s.resources[req.key()];
3904.             // Step 2: if the object exists, perform a check using a predicate on object
3905.             // The predicate: Is the current object owned by req.owner_ref?
