4067.                 ongoing_reconciles: s.ongoing_reconciles.insert(cr_key, initialized_ongoing_reconcile),
4068.                 scheduled_reconciles: s.scheduled_reconciles.remove(cr_key),
4069.                 reconcile_id_allocator: new_allocator,
4070.                 ..s
4071.             };
4072.             let output = ControllerActionOutput {
4073.                 send: Multiset::empty(),
4074.                 rpc_id_allocator: input.rpc_id_allocator,
4075.             };
4076.             (s_prime, output)
