4088.                 &&& s.ongoing_reconciles.contains_key(cr_key)
4089.                 &&& !(model.done)(s.ongoing_reconciles[cr_key].local_state)
4090.                 &&& !(model.error)(s.ongoing_reconciles[cr_key].local_state)
4091.                 &&& if s.ongoing_reconciles[cr_key].pending_req_msg is Some {
4092.                     &&& input.recv is Some
4093.                     &&& (input.recv->0.content.is_APIResponse() || input.recv->0.content.is_ExternalResponse())
4094.                     &&& resp_msg_matches_req_msg(input.recv->0, s.ongoing_reconciles[cr_key].pending_req_msg->0)
4095.                 } else {
4096.                     input.recv is None
4097.                 }
4098.             } else {
4099.                 false
4100.             }
4101.         },
4102.         transition: |input: ControllerActionInput, s: ControllerState| {
4103.             let cr_key = input.scheduled_cr_key->0;
4104.             let reconcile_state = s.ongoing_reconciles[cr_key];
4105.             let resp_o = if input.recv is Some {
4106.                 if input.recv->0.content.is_APIResponse() {
4107.                     Some(ResponseContent::KubernetesResponse(input.recv->0.content.get_APIResponse_0()))
4108.                 } else {
4109.                     Some(ResponseContent::ExternalResponse(input.recv->0.content.get_ExternalResponse_0()))
4110.                 }
4111.             } else {
4112.                 None
4113.             };
4114.             let (local_state_prime, req_o) = (model.transition)(reconcile_state.triggering_cr, resp_o, reconcile_state.local_state);
4115.             let (pending_req_msg, send, rpc_id_allocator_prime) = if req_o is Some {
4116.                 let pending_req_msg = match req_o->0 {
4117.                     RequestContent::KubernetesRequest(req) => {
4118.                         Some(controller_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
4119.                     },
4120.                     RequestContent::ExternalRequest(req) => {
4121.                         Some(controller_external_req_msg(controller_id, cr_key, input.rpc_id_allocator.allocate().1, req))
4122.                     }
4123.                 };
4124.                 (pending_req_msg, Multiset::singleton(pending_req_msg->0), input.rpc_id_allocator.allocate().0)
4125.             } else {
4126.                 (None, Multiset::empty(), input.rpc_id_allocator)
4127.             };
4128. 
4129.             let reconcile_state_prime = OngoingReconcile {
4130.                 pending_req_msg: pending_req_msg,
