 pub open spec fn handle_get_request(req: GetRequest, s: APIServerState) -> GetResponse {
     if !s.resources.contains_key(req.key) {
         // Get fails
         GetResponse{res: Err(APIError::ObjectNotFound)}
     } else {
         // Get succeeds
         GetResponse{res: Ok(s.resources[req.key])}
     }
